// Turns a failed execution into a structured Slack alert.
// Alerts carry IDs and error codes only: never contact details, and never raw
// errors, which can contain request headers with credentials.

const REDACTIONS = [
  /Bearer\s+[^\s"'\\]+/gi,
  /\bEAA[A-Za-z0-9]{10,}[^\s"'\\]*/g,
  /\bpat[A-Za-z0-9]{10,}\.[A-Za-z0-9]+/g,
  /\bxox[baprs]-[A-Za-z0-9-]+/g,
];
const redact = (text) => REDACTIONS.reduce((t, re) => t.replace(re, '[REDACTED]'), String(text ?? ''));

const event = $json;
const workflow = event.workflow?.name ?? 'unknown workflow';
const execution = event.execution ?? {};
const failedStep = execution.lastNodeExecuted ?? 'unknown step';
const raw = redact(execution.error?.message ?? 'No error message');
const [summary, ...detail] = raw.split('|').map((part) => part.trim());
const leadId = (raw.match(/lead ([0-9a-f-]{36})/i) ?? [])[1];

// What the failure means for the lead, so whoever is on call knows if it is urgent.
let impact = 'Check the execution to see what the failed step left behind.';
if (/CAPI|Meta/i.test(failedStep)) {
  impact = 'Lead is stored in Airtable. The Meta event is marked Failed and the replay workflow will retry it.';
} else if (/Airtable/i.test(failedStep)) {
  impact = 'Lead was not stored by n8n. The API fallback should have written it directly; confirm the record exists.';
}

const lines = [
  ':rotating_light: *Lead pipeline failure*',
  '',
  `*Workflow*  \`${workflow}\``,
  `*Failed step*  \`${failedStep}\``,
  leadId ? `*Lead*  \`${leadId}\`` : null,
  `*Error*  ${summary}`,
  detail.length ? `> ${detail.join(' | ').slice(0, 500)}` : null,
  '',
  `*Impact*  ${impact}`,
  execution.url ? `<${execution.url}|Open execution in n8n>` : null,
].filter((line) => line !== null);

return [{ json: { text: lines.join('\n'), lead_id: leadId ?? null } }];
